+
+export function toggleOrderedList(editor: EditorAPI): boolean {
+  return toggleList(
+    editor,
+    (line) => /^\d+\.\s/.test(line),
+    stripOl,
+    (line, i) => `${i + 1}. ` + stripAnyList(line),
