+  );
+}
+
+export function toggleUnorderedList(editor: EditorAPI): boolean {
+  return toggleList(
+    editor,
+    (line) => /^[-*+]\s/.test(line),
+    stripUl,
+    (line) => "- " + stripAnyList(line),
+    singleToggleUnorderedList,
+  );
+}
